public int superDigit(String n, int k) {
    long seed = 0;
    for (int i = 0; i < n.length(); i++) seed += n.charAt(i) - '0';
    seed *= k;                                 // k copies → multiply once
    while (seed >= 10) {                        // reduce to a single digit
        long s = 0;
        while (seed > 0) { s += seed % 10; seed /= 10; }
        seed = s;
    }
    return (int) seed;
}

