public int superDigit(String n, int k) {
    long m = 0;
    for (int i = 0; i < n.length(); i++) m += n.charAt(i) - '0';
    m *= k;                                    // collapse k copies
    if (m == 0) return 0;
    return (int) (1 + (m - 1) % 9);            // digital root
}

